def extract_grid(content, section_name):
    """Extract a grid from the given section of content"""
    m = re.search(rf'{section_name} \((\d+)x(\d+)\):', content)
    if not m:
        return None

    start = m.end()
    h, w = int(m.group(1)), int(m.group(2))

    grid = []
    pos = 0
    for _ in range(h):
        # Skip \n if present at start
        if pos < len(content) and content[pos:pos+2] == '\\n':
            pos += 2
        elif pos < len(content) and content[pos:pos+1] == '\\':
            return None  # Unexpected
        else:
            pos += 1

        # Parse the row
        row = []
        for col in range(w):
            while pos < len(content) and content[pos:pos+1].isspace():
                if pos+1 < len(content) and content[pos:pos+2] == '\\n':
                    break
                pos += 1
            if pos < len(content) and '0' <= content[pos] <= '9':
                row.append(int(content[pos]))
                pos += 1
            else:
                break

        grid.append(row)

        # Skip trailing whitespace and \n
        while pos < len(content):
            nc = content[pos:pos+1]
            if nc.isspace():
                if nc == '\\':
                    if pos+1 < len(content) and content[pos+1:pos+2] == 'n':
                        pos += 2
                    break
            elif nc.isspace():
                pos += 1
            else:
                break

    return grid

